// Resolve the exact floor crossing so the same release has the same outcome
// on a slow phone and a fast display; never grade after a frame overshoot.
function flightStep(prop,velocity,dt,floor){
 const gravity=9.81,height=Math.max(0,prop.position.y-floor);
 const landing=(velocity.y+Math.sqrt(velocity.y*velocity.y+2*gravity*height))/gravity;
 const step=Math.max(0,Math.min(dt,landing));
 prop.position.addScaledVector(velocity,step);prop.position.y-=gravity*step*step/2;velocity.y-=gravity*step;
 return {step,landed:landing<=dt};
}
function crossedHole(from,to){
 const dx=to.x-from.x,dz=to.z-from.z,length=dx*dx+dz*dz;
 const t=length?THREE.MathUtils.clamp((-from.x*dx+(-.5-from.z)*dz)/length,0,1):0;
 return Math.hypot(from.x+dx*t,from.z+dz*t+.5)<.13;
}
export function traditional(ctx){const constructors={pilolo:Pilolo,stay:Stay,alikoto:Alikoto,tumatu:Tumatu,kpitinge:PegToss,alasa:Alasa,numbers:Numbers,chempe:Chempe,pempenaa:Pempenaa,mbobagor:Mbobagor};return constructors[ctx.game.id]?new constructors[ctx.game.id](ctx):null;}
class Pilolo extends Mode{
 constructor(ctx){super(ctx);this.you=this.player(-6,14);this.world.follow?.(this.you);this.solids=this.venue.solids;this.home={x:-6,z:14};this.seekers=[this.player(-7.2,14,0x397e95),this.player(-4.8,14,0xc09c4d)];this.round=0;this.scores=[0,0,0];this.carried=null;this.places=[];this.circle(-6,14,1.4);this.text('HOME',-6,.1,14,'#ead6a3',.35);
 const locations=[[-14,-13],[-5,-13],[5,-13],[14,-13],[-14,-4],[-5,-4],[6,-4],[14,-3],[-14,5],[-4,4],[6,6],[14,13],[0,14],[8,14]];
 locations.forEach(([x,z],i)=>{const g=new THREE.Group();g.position.set(x,0,z);this.root.add(g);const lid=i%3===0?box(.65,.045,.5,0x8a7960,0,.47,0,g):cylinder(.38,.4,.05,0x9b8764,0,.52,0,g,16);if(i%3===0)box(.65,.45,.5,0x716148,0,.225,0,g);else cylinder(.36,.3,.48,i%2?0x737c67:0x927a57,0,.24,0,g,16);const stick=cylinder(.025,.035,.4,0xc5b382,0,.24,0,g,8);stick.visible=false;this.places.push({x,z,g,lid,stick,lidY:lid.position.y,has:false,opened:false,name:i%3===0?'doorstep box':i%2?'water pot':'basket'});});
 this.setActions([{id:'search',label:'Search / collect',key:'Space'},{id:'sprint',label:'Sprint',key:'Shift',hold:true}]);this.newRound();
 }
 newRound(){this.phase='ready';this.time=0;this.carried=null;this.you.position.set(-6,0,14);this.you.userData.run=0;this.input.target=null;this.route=[];for(const q of this.places){q.has=false;q.opened=false;q.lid.position.y=q.lidY;q.lid.rotation.z=0;q.stick.visible=false;q.stick.position.set(0,.24,0);}const shuffled=this.places.map((_,i)=>i).sort(()=>Math.random()-.5);shuffled.slice(0,3).forEach(i=>this.places[i].has=true);this.seekers.forEach((p,i)=>{p.position.set(i?-7.2:-4.8,0,14);Object.assign(p.userData,{found:false,choice:shuffled[3+i],searchDelay:0,route:[],planning:0});});this.note('The leader has hidden three sticks around the neighbourhood. Wait for PILOLO!');}
 action(){if(this.phase!=='search')return;if(this.carried){if(distance(this.you,this.home)<1.5)this.endRound(0);return;}const q=this.places.find(p=>distance(this.you,p)<1.5&&!p.opened);if(!q){this.note('Search a covered basket, pot or box near a doorway. Move close first.');return;}this.open(q);this.you.userData.pose='reach';this.delay=.4;if(q.has){this.carried=q.stick;q.has=false;q.stick.visible=true;this.note('Found one! Race HOME through the alleys.');this.ui.sound('point');}else this.note('Empty '+q.name+'. Search another courtyard.');}
 open(q){q.opened=true;q.lid.rotation.z=.65;q.lid.position.y=q.lidY+.15;this.ui.sound('stone');}
 endRound(winner){if(this.phase==='result')return;if(winner!==null)this.scores[winner]++;this.round++;this.phase='result';this.time=0;this.input.target=null;this.note(winner===0?'First home! You win this round.':winner===null?'No one returned. The leader hides again.':'A rival got home first. New hiding places next round.');this.ui.sound(winner===0?'goal':'call');}
 hit({point}){this.input.target=point;this.route=routeTo(this.you.position,point,this.solids);}
 walk(p,target,speed,dt){const v=new THREE.Vector3(target.x-p.position.x,0,target.z-p.position.z);if(v.length()<.2)return 0;v.normalize().multiplyScalar(speed);slideMove(p.position,v,dt,this.solids);p.rotation.y=Math.atan2(v.x,v.z);return 1;}
 update(dt){this.status(`YOU ${this.scores[0]} · RIVALS ${this.scores[1]+this.scores[2]}`,`ROUND ${Math.min(3,this.round+1)} / 3`);if(this.phase==='ready'){if(this.time>2.2){this.phase='search';this.time=0;this.note('PILOLO! Search the neighbourhood, find one stick, race home.');this.ui.sound('call');}return;}if(this.phase==='result'){if(this.time>2){if(this.round>=3){this.score=this.scores[0];return this.finish(this.scores[0]>=2?'QUICKEST IN THE NEIGHBOURHOOD':'THE SEARCH IS OVER',`${this.scores[0]} of 3 races won.`,this.scores[0]>=2);}this.newRound();}return;}
 const raw=this.world.movementVector?.(this.input.vector())||this.input.vector(),v=new THREE.Vector3(raw.x,0,raw.z),speed=this.input.sprint?6.6:4.6;if(v.length()>.1){this.route=[];v.multiplyScalar(speed);slideMove(this.you.position,v,dt,this.solids);this.you.rotation.y=Math.atan2(v.x,v.z);this.you.userData.run=1;}else if(this.route?.length){this.you.userData.run=this.walk(this.you,this.route[0],speed,dt);if(distance(this.you,this.route[0])<.3)this.route.shift();}else this.you.userData.run=0;
 if(this.delay>0){this.delay-=dt;if(this.delay<=0)this.you.userData.pose='idle';}if(this.carried){this.carried.position.set(this.you.position.x-this.carried.parent.position.x,.95,this.you.position.z-this.carried.parent.position.z);if(distance(this.you,this.home)<1.3)this.endRound(0);}
 this.seekers.forEach((p,i)=>{if(this.networked||this.phase!=='search')return;const u=p.userData;let q=u.found?this.home:this.places[u.choice];if(!u.found&&q.opened){const options=this.places.map((q,j)=>!q.opened?j:-1).filter(j=>j>=0);u.choice=options[Math.floor(Math.random()*options.length)]??u.choice;q=this.places[u.choice];u.route=[];}u.planning-=dt;if(!u.route.length||u.planning<=0){u.route=routeTo(p.position,new THREE.Vector3(q.x,0,q.z),this.solids);u.planning=3;}if(u.route.length){u.run=this.walk(p,u.route[0],(u.found?4.1:3.5)*this.difficultyTuning.speed,dt);if(distance(p,u.route[0])<.3)u.route.shift();}if(distance(p,q)<1.15){if(u.found){this.endRound(i+1);return;}u.searchDelay+=dt;u.pose='reach';u.run=0;if(u.searchDelay>.9*this.difficultyTuning.window){this.open(q);if(q.has){u.found=true;q.has=false;q.stick.visible=false;u.route=[];}u.searchDelay=0;u.pose='idle';}}});if(this.time>150)this.endRound(null);
 }
}
class Alikoto extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([.1,.4,.5,0,.08,0]);this.you=this.player(-.55,-.4);this.you.visible=false;this.you.rotation.y=1.9;this.you.userData.pose='knees';this.prop=new THREE.Group();this.root.add(this.prop);cylinder(.19,.19,.065,0xa6a59c,0,0,0,this.prop,32);cylinder(.04,.045,.64,0x284f66,0,.34,0,this.prop,16);cylinder(.045,.045,.025,0x163a50,0,.667,0,this.prop,16);box(.018,.3,.025,0x346984,.048,.48,0,this.prop);this.prop.scale.setScalar(.08);this.prop.position.set(0,.0026,0);ring(.17,0xe1d4b4,0,0,this.root,.0015,.002);this.overview=false;this.cycleCamera=()=>{this.overview=!this.overview;this.you.visible=this.overview;this.world.setCamera(this.overview?[1.3,2,2.6,0,.25,0]:[.1,.4,.5,0,.08,0]);};this.phase='ready';this.attempt=0;this.power=.45;this.charge=null;this.v=new THREE.Vector3();this.setActions([{id:'strike',label:'Strike',key:'Space',charge:true},{id:'power',label:'Power',key:'E'}]);this.note('Hold Strike, then release. Land the pen-cap toy upright inside the chalk circle. C changes view.');}
 hold(id){if(id==='strike'&&this.phase==='ready')this.charge=this.age;}
 action(id){if(this.phase!=='ready')return;if(id==='power'){this.power=this.power>=.8?.3:this.power+.1;return;}if(this.charge!==null)this.power=THREE.MathUtils.clamp(.25+(this.age-this.charge)*.55,.25,.9);this.charge=null;this.phase='flight';this.time=0;this.prop.position.set(0,.025,0);this.prop.rotation.set(0,0,0);this.v.set(.06,1+this.power*1.5,.05);this.angular=14+this.power*10;this.you.userData.pose='reach';this.ui.sound('clap');}
 update(dt){const power=this.charge===null?this.power:THREE.MathUtils.clamp(.25+(this.age-this.charge)*.55,.25,.9);this.status(`${this.score} CLEAN LANDINGS`,`${Math.min(5,this.attempt+1)} / 5 · STRENGTH ${Math.round(power*100)}%`);if(this.phase==='flight'){const flight=flightStep(this.prop,this.v,dt,.0026);this.prop.rotation.z+=this.angular*flight.step;this.prop.rotation.y+=flight.step*3;if(flight.landed){const up=Math.cos(this.prop.rotation.z),ok=up>1-.08*this.difficultyTuning.window&&Math.hypot(this.prop.position.x,this.prop.position.z)<.17;this.prop.position.y=ok?.0026:.0152;this.prop.rotation.z=ok?0:Math.PI/2;if(ok)this.score++;this.attempt++;this.phase='result';this.time=0;this.note(ok?'Landed on its metal base.':'On its side. Adjust the force of the next strike.');this.ui.sound(ok?'point':'stone');}}else if(this.phase==='result'&&this.time>1.5){if(this.attempt>=5)return this.finish('ALIKOTO — ROUND COMPLETE',`${this.score} upright landings in five strikes.`,this.score>=3);this.phase='ready';this.you.userData.pose='knees';this.prop.position.set(0,.0026,0);this.prop.rotation.set(0,0,0);}}
}
class PegToss extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([3,3.8,9,0,.5,-1]);this.you=this.player(-1,3);this.you.rotation.y=Math.PI;this.prop=new THREE.Group();this.root.add(this.prop);cylinder(.04,.065,.8,0xc3b387,0,0,0,this.prop,12);cylinder(.11,.07,.2,0x797a70,0,-.38,0,this.prop,12);this.prop.position.set(0,1.1,3);const mound=sphere(1.3,0xba8c62,0,.07,-3,this.root,32);mound.scale.y=.22;this.phase='ready';this.attempt=0;this.aim=0;this.v=new THREE.Vector3();this.setActions([{id:'throw',label:'Toss peg',key:'Space'}]);this.note('Aim at the mound. Release near vertical; the actual landing decides the point.');}
 action(){if(this.phase!=='ready')return;this.phase='flight';this.time=0;this.v.set(Math.sin(this.aim)*6,4.3,-6);this.angular=6.1;this.you.userData.pose='point';this.ui.sound('swing');}
 hit({point}){if(this.phase==='ready')this.aim=THREE.MathUtils.clamp(Math.atan2(point.x,3-point.z),-.5,.5);}
 update(dt,t){this.status(`${this.score} PLANTED`,`${Math.min(5,this.attempt+1)} / 5`);if(this.phase==='ready'){this.aim=THREE.MathUtils.clamp(this.aim+this.input.vector().x*dt*.5,-.5,.5);this.prop.rotation.z=Math.sin(t*3)*.55;this.prop.rotation.y=this.aim;}else if(this.phase==='flight'){const flight=flightStep(this.prop,this.v,dt,.45);this.prop.rotation.z+=this.angular*flight.step;if(flight.landed){const inMound=distance(this.prop,{x:0,z:-3})<1.2,up=Math.cos(this.prop.rotation.z)>1-.09*this.difficultyTuning.window,ok=inMound&&up;if(ok)this.score++;this.prop.position.y=ok?.5:.12;this.prop.rotation.z=ok?0:Math.PI/2;this.attempt++;this.phase='result';this.time=0;this.note(ok?'The weighted point planted in the mound.':!inMound?'Outside the mound. Adjust your aim.':'The peg fell sideways. Adjust the release timing.');this.ui.sound(ok?'point':'stone');}}else if(this.time>1.5){if(this.attempt>=5)return this.finish('KPITINGE — ROUND COMPLETE',`${this.score} of five pegs planted upright.`,this.score>=3);this.phase='ready';this.prop.position.set(0,1.1,3);this.you.userData.pose='idle';}}
}
class Tumatu extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([2.4,7,10,0,.1,1]);this.you=this.player(0,6.5);this.you.rotation.y=Math.PI;this.positions=[[-.45,5],[.45,4],[-.45,3],[.45,2],[-.45,1],[.45,0],[-.45,-1],[.45,-2]];this.route=[0,1,2,4,5,6,7,6,5,4,2,1,0];this.next=0;for(let i=0;i<8;i++){const [x,z]=this.positions[i];for(const [dx,dz,w,d]of [[0,-.45,.9,.018],[0,.45,.9,.018],[-.45,0,.018,.9],[.45,0,.018,.9]])box(w,.01,d,0xddd2b4,x+dx,.018,z+dz,this.root);this.text(String(i+1),x,.05,z,'#ded1b0',.22);}this.marker=sphere(.075,0x6b5b45,.45,.06,2,this.root,12);this.marker.scale.y=.4;this.you.userData.pose='left';this.charge=null;this.air=0;this.velocity=new THREE.Vector3();this.aim=null;this.markerCollected=false;this.landing=this.circle(0,5,.18,0xf2bd51);this.setHopActions();this.note('Marker in square 4. Hop out and back on one foot. Hold Hop longer for the gap. Tap a square to aim.');}
 setHopActions(){this.setActions([{id:'hop',label:'Hop',key:'Space',charge:true,disabled:this.needsMarker()},{id:'pickup',label:'Pick marker',key:'E',disabled:!this.needsMarker()}]);}
 needsMarker(){return this.next===10&&!this.markerCollected;}
 hold(id='hop'){if(id==='hop'&&this.air<=0&&!this.needsMarker())this.charge=this.age;}
 hit({point}){if(!this.air&&point)this.aim=point.clone();}
 landingPoint(charge){const q=this.positions[this.route[this.next]],target=this.aim||new THREE.Vector3(q[0],0,q[1]),dir=target.clone().sub(this.you.position);dir.y=0;return this.you.position.clone().addScaledVector(dir.normalize(),.8+charge*1.4);}
 action(id='hop'){
  if(this.air>0||this.done||this.landWait>0)return;
  if(id==='pickup'){if(this.needsMarker()){this.markerCollected=true;this.marker.visible=false;this.you.userData.pose='knees';this.landWait=.4;this.ui.sound('stone');this.setHopActions();this.note('Marker collected. Hop over the gap and finish the return.');}return;}
  if(this.needsMarker())return this.note('Balance on square 5 and pick up your marker before returning.');
  const charge=this.charge===null?.4:THREE.MathUtils.clamp(this.age-this.charge,.35,1.3);this.charge=null;this.from=this.you.position.clone();this.destination=this.landingPoint(charge);this.velocity.copy(this.destination).sub(this.from).divideScalar(.62);this.air=.62;this.you.rotation.y=Math.atan2(this.velocity.x,this.velocity.z);this.ui.sound('jump');
 }
 update(dt){
  this.status(`${this.next} / ${this.route.length} HOPS`,this.needsMarker()?'PICK UP THE MARKER':`${this.next<7?'OUTWARD':'RETURN'} · ${this.markerCollected?'MARKER COLLECTED':'SKIP 4'}`);
  if(this.landWait>0){this.landWait-=dt;if(this.landWait<=0)this.you.userData.pose='left';return;}
  if(this.air<=0){const charge=this.charge===null?.4:THREE.MathUtils.clamp(this.age-this.charge,.35,1.3),preview=this.landingPoint(charge),q=this.positions[this.route[this.next]];this.landing.position.set(preview.x,.035,preview.z);this.landing.visible=!this.needsMarker();this.landing.material.color.set(Math.abs(preview.x-q[0])<.4*Math.min(1.1,this.difficultyTuning.window)&&Math.abs(preview.z-q[1])<.4*Math.min(1.1,this.difficultyTuning.window)?0x73b784:0xd78b4c);this.ui.power?.(this.charge===null?0:charge/1.3);return;}
  this.landing.visible=false;const step=Math.min(dt,this.air);this.you.position.addScaledVector(this.velocity,step);this.air-=step;this.you.userData.jump=Math.sin(this.air/.62*Math.PI)*.55;
  if(this.air<=0){this.you.userData.jump=0;const q=this.positions[this.route[this.next]],inside=Math.abs(this.you.position.x-q[0])<.4*Math.min(1.1,this.difficultyTuning.window)&&Math.abs(this.you.position.z-q[1])<.4*Math.min(1.1,this.difficultyTuning.window);
   if(inside){this.next++;this.score=this.next;this.aim=null;this.ui.sound('step');this.landWait=.13;if(this.next>=this.route.length)return this.finish('OUT AND BACK','You collected the marker and kept your hops inside the chalk.');this.setHopActions();this.note(this.needsMarker()?'Balance here and pick up the marker with E.':'Next: square '+(this.route[this.next]+1)+'. Watch the landing ring; hold longer for the gap.');}
   else{this.you.position.copy(this.from);this.aim=null;this.note('Foot outside the chalk. Regain your balance and retry.');this.ui.sound('miss');this.landWait=.25;}
  }
 }
}
class Alasa extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([1.5,3.7,5,0,.1,.7]);this.you=this.player(-1.5,1);this.you.rotation.y=Math.PI/2;this.you.userData.pose='knees';this.other=this.player(1.5,1,0x3f7f82);this.other.rotation.y=-Math.PI/2;this.other.userData.pose='knees';cylinder(.14,.12,.025,0x342c22,0,.005,-.5,this.root,24);ring(.17,0x82745b,0,-.5,this.root,.018);this.seed=sphere(.075,0x56301c,0,.06,2.2,this.root,20);this.seed.scale.set(.7,.6,1.6);this.seed.material.roughness=.28;this.turn=0;this.scores=[0,0];this.attempts=[0,0];this.phase='aim';this.power=.55;this.aim=0;this.charge=null;this.v=new THREE.Vector3();this.setActions([{id:'flick',label:'Flick seed',key:'Space',charge:true},{id:'power',label:'Set strength',key:'E'}]);this.note('Five seeds each. Aim at the little hole; hold Flick to set strength. Sunk seeds count.');}
 hold(){if(this.turn===0&&this.phase==='aim')this.charge=this.age;}
 hit({point}){if(this.phase==='aim'&&this.turn===0)this.aim=THREE.MathUtils.clamp(Math.atan2(point.x,2.2-point.z),-.5,.5);}
 action(id){if(this.phase!=='aim'||this.turn!==0)return;if(id==='power'){this.power=this.power>=.9?.3:this.power+.1;return;}if(this.charge!==null)this.power=THREE.MathUtils.clamp(.25+(this.age-this.charge)*.6,.2,1);this.charge=null;this.flick(this.power,this.aim);}
 flick(power,aim){this.phase='rolling';this.time=0;this.seed.position.set(0,.06,2.2);this.v.set(Math.sin(aim)*power*10.4,0,-Math.cos(aim)*power*10.4);(this.turn?this.other:this.you).userData.pose='reach';this.ui.sound('stone');}
 update(dt){this.status(`YOU ${this.scores[0]} — ${this.scores[1]} THEM`,`${this.turn?'THEIR':'YOUR'} SEED ${Math.min(5,this.attempts[this.turn]+1)} / 5`);if(this.phase==='aim'){this.aim=THREE.MathUtils.clamp(this.aim+this.input.vector().x*dt*.3,-.5,.5);if(!this.networked&&this.turn===1&&this.time>1.2)this.flick(.54+(Math.random()-.5)*.12*this.difficultyTuning.error,(Math.random()-.5)*.07*this.difficultyTuning.error);}else if(this.phase==='rolling'){const before=this.seed.position.clone(),drag=Math.exp(-2.1*dt);this.seed.position.addScaledVector(this.v,(1-drag)/2.1);this.v.multiplyScalar(drag);this.seed.rotation.x-=distance(before,this.seed)/.075;const sunk=crossedHole(before,this.seed.position);if(sunk||this.v.length()<.08||this.time>3){if(sunk){this.scores[this.turn]++;this.seed.position.y=-.1;}this.attempts[this.turn]++;this.phase='result';this.time=0;this.note(sunk?'In the hole. One seed won.':'Missed the hole. Next seed.');this.ui.sound(sunk?'point':'stone');}}else if(this.time>1.2){if(this.attempts.every(n=>n>=5)){this.score=this.scores[0];return this.finish(this.scores[0]===this.scores[1]?'HONOURS EVEN':this.scores[0]>this.scores[1]?'YOUR SEEDS WIN':'THEY TAKE THIS ROUND',`${this.scores[0]} – ${this.scores[1]} seeds sunk.`,this.scores[0]>=this.scores[1],this.scores[0]===this.scores[1]?'draw':undefined);}this.turn=1-this.turn;this.phase='aim';this.time=0;this.seed.position.set(0,.06,2.2);this.you.userData.pose=this.other.userData.pose='knees';}}
}
class Numbers extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([0,4,9,0,1,0]);this.you=this.player(0,3);this.you.rotation.y=Math.PI;this.group=[];for(let i=0;i<4;i++){const a=i*Math.PI/2,p=this.player(Math.sin(a)*2.8,Math.cos(a)*2.8-1,i%2?0x387b86:0xa88b42);p.rotation.y=a+Math.PI;this.group.push(p);}this.round=0;this.phase='others';this.questions=[[8,7,9],[13,15,12],[21,25,23],[31,33,35],[42,43,49],[51,53,57],[63,65,67],[71,77,81]];this.correct=[1,0,2,0,1,1,2,0];this.setActions([{id:'ready',label:'Ready',key:'Space'}]);this.note('Players name primes in turn. Your response window gets shorter each round.');}
 action(id){if(this.phase!=='you')return;const ok=Number(id)===this.correct[this.round];if(!ok)return this.finish('OUT OF THE CIRCLE',`${this.questions[this.round][this.correct[this.round]]} was prime. You cleared ${this.score} turns.`,false);this.score++;this.round++;this.you.userData.pose='point';this.ui.sound('point');if(this.round>=8)return this.finish('QUICK WITH NUMBERS','Eight prime responses before the clock.');this.phase='others';this.time=0;this.note('Good. Listen while the turn comes around.');}
 update(dt,t){this.status(`${this.score} TURNS CLEARED`,this.phase==='you'?`${Math.max(0,(3.5-this.round*.2)*this.difficultyTuning.window-this.time).toFixed(1)}s TO ANSWER`:'THE CIRCLE IS ANSWERING');if(this.phase==='others'){this.group.forEach((p,i)=>p.userData.pose=Math.floor(this.time/.45)%4===i?'point':'idle');if(this.time>1.8){this.phase='you';this.time=0;this.you.userData.pose='idle';this.setActions(this.questions[this.round].map((n,i)=>({id:String(i),label:String(n),key:['Space','E','Q'][i]})));this.note('Your turn. Name a prime.');}}else if(this.time>(3.5-this.round*.2)*this.difficultyTuning.window)this.finish('THE TURN PASSED YOU',`${this.score} turns cleared. Try a quicker response.`,false);}
}
class Chempe extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([0,2.7,6.2,0,1,0]);this.you=this.player(-1,0);this.other=this.player(1,0,0x397d7f);this.you.rotation.y=Math.PI/2;this.other.rotation.y=-Math.PI/2;this.food=new THREE.Group();this.root.add(this.food);for(let i=0;i<4;i++)sphere(.09,0xc78c38,(i%2)*.17,0,Math.floor(i/2)*.17,this.food,16);this.round=0;this.phase='wait';this.setActions([{id:'no',label:'No Chem pe!',key:'Space'},{id:'claim',label:'Chempε!',key:'E'}]);this.prepare();}
 prepare(){this.holder=this.round%2===0;this.phase='wait';this.time=0;this.revealAt=1+Math.random()*2;this.cpuAt=(.65+Math.random()*.6)*this.difficultyTuning.window;this.food.visible=false;this.you.userData.pose=this.other.userData.pose='idle';this.note(this.holder?'You hold the food. When it appears, call “No Chem pe!” first.':'You are the claimant. When food appears, call “Chempε!” before the exemption.');}
 action(id){if(this.phase==='wait'){this.resolve(false,'Too early. Wait until the food is revealed.');return;}if(this.phase!=='reveal')return;const ok=this.holder?id==='no':id==='claim';this.resolve(ok,ok?(this.holder?'Exemption remembered. You keep your portion.':'A fair claim. The portions are shared.'):'Wrong call for your role.');}
 resolve(ok,message){if(ok)this.score++;this.round++;this.phase='result';this.time=0;this.food.visible=true;this.food.position.set(0,1,.3);this.food.children.forEach((p,i)=>{p.position.x=(i<2?-.65:.65)+(i%2)*.16;});this.you.userData.pose=this.other.userData.pose='reach';this.note(message);this.ui.sound(ok?'point':'miss');}
 update(){this.status(`${this.score} QUICK CALLS`,`${Math.min(6,this.round+1)} / 6 · ${this.holder?'FOOD-HOLDER':'CLAIMANT'}`);if(this.phase==='wait'&&this.time>this.revealAt){this.phase='reveal';this.time=0;this.food.visible=true;this.food.children.forEach((p,i)=>p.position.x=(i%2)*.17);this.food.position.set(this.holder?-.65:.65,1,.2);this.note(this.holder?'Food is out — No Chem pe!':'Food is out — claim Chempε!');}else if(this.phase==='reveal'&&this.time>this.cpuAt)this.resolve(false,this.holder?'They claimed a share before your exemption.':'They said “No Chem pe” first.');else if(this.phase==='result'&&this.time>1.4){if(this.round>=6)return this.finish('THE PACT REMEMBERED',`${this.score} of six calls made in time.`,this.score>=4);this.prepare();}}
}
class Pempenaa extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([0,4.6,7,0,.3,0]);this.people=[];this.legs=Array.from({length:8},()=>true);for(let i=0;i<4;i++){const p=this.player((i-1.5)*1.3,0,i===0?this.settings.color:i%2?0x426d7f:0xaa8d4b);p.userData.pose='sit';this.people.push(p);}this.leader=this.player(0,3,0x687a55);this.leader.rotation.y=Math.PI;this.leader.userData.pose='point';this.pointer=sphere(.045,0xd4c6a5,0,.08,1,this.root);this.index=0;this.ticks=0;this.phrase=9;this.phase='count';this.rank=[];this.setActions([{id:'left',label:'Fold left leg',key:'Space'},{id:'right',label:'Fold right leg',key:'E'}]);this.note('The count passes over each extended leg. Fold only the selected leg when the phrase ends.');}
 activeLegs(){return this.legs.map((v,i)=>v?i:-1).filter(i=>i>=0);}
 fold(i){this.legs[i]=false;const person=Math.floor(i/2),left=this.legs[person*2],right=this.legs[person*2+1];this.people[person].userData.pose=!left&&!right?'knees':!left?'fold-left':'fold-right';if(!left&&!right&&!this.rank.includes(person)){this.rank.push(person);if(person===0){this.score=5-this.rank.length;return this.finish('BOTH LEGS WITHDRAWN',`You finished ${['first','second','third','fourth'][this.rank.length-1]}. Phrase length is an arcade counting choice.`,this.rank.length===1);}}this.phase='count';this.time=0;this.ticks=0;this.phrase=7+Math.floor(Math.random()*7);this.note('A new phrase begins. Follow the remaining legs.');}
 action(id){if(this.phase==='selected'&&this.selected<2){const chosen=id==='left'?0:1;if(chosen===this.selected){this.ui.sound('point');this.fold(chosen);}else this.note('Only the selected leg folds this time.');}}
 update(){this.status(`${this.legs.slice(0,2).filter(v=>!v).length} / 2 LEGS FOLDED`,this.phase==='selected'?'PHRASE END':'FOLLOW THE COUNT');if(this.phase==='count'&&this.time>.36*this.difficultyTuning.window){this.time=0;const legs=this.activeLegs();if(!legs.length)return;this.index=(this.index+1)%legs.length;this.selected=legs[this.index];this.pointer.position.set((Math.floor(this.selected/2)-1.5)*1.3+(this.selected%2?.16:-.16),.08,.8);this.ui.sound('stone');this.ticks++;if(this.ticks>=this.phrase){this.phase='selected';this.time=0;this.note(this.selected<2?`Your ${this.selected===0?'left':'right'} leg. Fold it.`:'The selected player folds one leg.');}}else if(this.phase==='selected'&&this.selected>=2&&this.time>.7)this.fold(this.selected);else if(this.phase==='selected'&&this.selected<2&&this.time>2.5*this.difficultyTuning.window){this.phase='count';this.time=0;this.ticks=0;this.note('Missed the fold. Keep your leg out and follow the next phrase.');}}
}
class Mbobagor extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([0,5.2,7.5,0,.3,0]);this.people=[];this.piles=Array(6).fill(1);this.stones=[];this.beat=0;this.lastBeat=0;this.passed=false;this.period=1.5;for(let i=0;i<6;i++){const a=i*Math.PI/3,p=this.player(Math.sin(a)*2.3,Math.cos(a)*2.3,i===0?this.settings.color:i%2?0x4a7b7a:0xb09451);p.rotation.y=a+Math.PI;p.userData.pose='knees';this.people.push(p);this.stones.push([]);for(let n=0;n<3;n++){const stone=sphere(.09,0x7a7262,Math.sin(a)*1.65,.08+n*.14,Math.cos(a)*1.65,this.root,10);stone.scale.y=.6;stone.visible=n===0;this.stones[i].push(stone);}}this.setActions([{id:'pass',label:'Pass stone',key:'Space'}]);this.note('Listen to three count-in claps, then pass on the beat. A missed pass leaves a stone in your pile.');}
 action(){const within=this.time<.32*this.difficultyTuning.window||this.time>this.period-.28*this.difficultyTuning.window;if(within&&!this.passed){this.passed=true;this.people[0].userData.pose='reach';this.ui.sound('stone');}else if(!within)this.note('Find the shared beat. Pass with the next clap.');}
 update(dt){this.period=Math.max(.85,1.5-this.score*.035)*this.difficultyTuning.window;this.status(`${this.score} PASSES`,this.beat<3?`COUNT IN · ${3-this.beat} CLAPS`:`${this.piles[0]} STONES IN YOUR PILE`);if(this.time>=this.period){this.time-=this.period;this.beat++;if(this.beat>3){if(this.passed){this.score++;this.piles[0]=Math.max(1,this.piles[0]-1);}else{this.piles[0]++;this.note('One incoming stone, one missed pass. Your pile grew.');}}if(this.beat===3)this.note('Your turn — pass on the clap. A clean pass clears an extra stone.');this.passed=false;this.ui.sound('clap');this.people.forEach((p,i)=>p.userData.pose=i?'reach':'knees');if(this.piles[0]>=3)return this.finish('THREE STONES COLLECTED',`${this.score} passes in rhythm. Listen for the next beat.`,false);if(this.score>=16)return this.finish('THE CIRCLE STAYS TOGETHER','Sixteen passes with the group.');}
 const progress=THREE.MathUtils.clamp(this.time/.32,0,1);for(let i=0;i<6;i++){const a=i*Math.PI/3,b=(i+1)%6*Math.PI/3;this.stones[i].forEach((s,n)=>{s.visible=n<this.piles[i];if(n===0&&i!==0||n===0&&this.passed){s.position.x=THREE.MathUtils.lerp(Math.sin(a)*1.65,Math.sin(b)*1.65,progress);s.position.z=THREE.MathUtils.lerp(Math.cos(a)*1.65,Math.cos(b)*1.65,progress);s.position.y=.08+Math.sin(progress*Math.PI)*.18;}else s.position.set(Math.sin(a)*1.65,.08+n*.14,Math.cos(a)*1.65);});}if(this.time>.4)this.people.forEach(p=>p.userData.pose='knees');}
}
